tasks.initialCode:
const BUDGET = 1000;
function cost(invocations, backEdges) {
  return invocations + backEdges;
}
const a = cost(200, 0);     // function A: 200 calls, no loop
const b = cost(1, 5000);    // function B: 1 call, 5000 back-edges
const aTrips = a >= BUDGET;
const bTrips = b >= BUDGET;
const who = bTrips && !aTrips ? 'B' : (aTrips && !bTrips ? 'A' : 'both/none');
const overshoot = b - BUDGET;
console.log('trips=' + who + ' overshoot=' + overshoot);

tasks.starter:
const THRESHOLD = 1000;
// Does this function tier up? Budget is spent by invocations AND loop back-edges.
function tiersUp(invocations, backEdges) {
  const spent = invocations; // count work toward the tier-up threshold
  return spent >= THRESHOLD;
}

tasks.verify:
const config = tiersUp(1, 0);          // should NOT tier up
const hotLoop = tiersUp(1, 1000000);   // SHOULD tier up via OSR
const busyCalls = tiersUp(5000, 0);    // should tier up on invocations alone
const ok = config === false && hotLoop === true && busyCalls === true;
console.log(ok ? 'PASS' : 'FAIL config=' + config + ' hotLoop=' + hotLoop + ' busyCalls=' + busyCalls);
